-- c006-v011: Dekho kitne–bade tumhe aksharonse maine–likha us apne haath.
-- c006-v012: Jitne chahte–hain achchhe–dikhna mein shareer, yahi majboor–karte–hain tumhe khatna–karvane, keval taki us krus ke Khristos (Yeshu) nahi sataye–jaayein.
-- c006-v013: na–hi kya un khatna–karvanevale khud vyavastha paalan–karte–hain; parantu chahte–hain tumhe khatna–karvana, taki mein us tumhare shareer ghamand–karein.
-- c006-v014: mujhse parantu, nahi ho ghamand–karna, agar nahi mein us krus ke Prabhu hamare, Yeshu Khristos, dwara jiske mujhe sansar krus–par–chadhaaya–gaya, aur–main sansar–ko.
-- c006-v015: na–to kya khatna kuch hai, na–to khatnarahita; parantu nayi srishti.
-- c006-v016: aur jitne us niyam is chalenge, shanti par unhe, aur daya; aur par us Israel ke Parameshwar.
-- c006-v017: Us aage, kathinaaiyaan mujhe koi–bhi na–de; main kya un nishaniyaan ke Yeshu, mein us shareer mere rakhta–hun.
-- c006-v018: Us anugrah ke Prabhu hamare, Yeshu Khristos, saath us aatma tumhari, bhaiyo. Amen.

BEGIN;
-- === Chapter 1 Verse 1 ===
-- 4800100101: Παῦλος, (G3972) → "Paulos," [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'hin'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '4800100101' AND p.language_id = (SELECT id FROM language WHERE code = 'hin') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '4800100101' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Paulos,', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '4800100101' AND p.language_id = (SELECT id FROM language WHERE code = 'hin') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
